from prep import *
for k in ['en','da']:
 g=rd('source-onboarding-'+k+'.json');D=rd('modern-'+k+'.json')['chapters'][0];g.update(openingText=D['paragraphs'][0],openingChapterLabel=D['title'])
 a=g['angleCards'];c=g['cast'];q=g['acclaim'];w=g['whyItMatters']
 if k=='en':
  g['about']="Lear plans to give away his kingdom and keep a hundred knights. With the court watching, he asks his three daughters which of them loves him most. Goneril and Regan oblige. Cordelia, his favorite, says she loves him as a daughter should. Lear gives her share to her sisters and banishes Kent for objecting. The King of France marries Cordelia without a dowry.\n\nGloucester also mistakes which child he can trust. His son Edmund uses a forged letter to turn him against Edgar, his heir. Edgar escapes by taking on the voice and rags of a wandering beggar. When Lear loses his shelter and Gloucester loses his sight, both fathers find themselves depending on people they once barely noticed.\n\nTwo early printed versions survive, the 1608 Quarto and the 1623 Folio. This edition combines readings from both. It includes Lear’s mock trial of his daughters and gives the play’s last speech to Edgar."
  a[1].update(text="Caught in the storm, Lear notices his Fool shivering. Soon he is asking how anyone without a roof survives such a night. Listen to how the object of his concern changes.")
  a[3].update(text="Cordelia and Lear find each other again. In prison he imagines the two of them telling stories and singing. Listen to what becomes of that future in the last scene.")
  for v in a:v['title']=v['title'].rstrip('.')
  c[0]['description']="Lear says he is over eighty. He gives away the land and the power to govern but expects to keep his title, his knights and his daughters’ obedience. Out in the storm, even finding shelter for the Fool becomes a question he has to answer himself."
  c[1]['description']="Lear’s youngest daughter answers her father plainly and leaves without a dowry as Queen of France. At Dover she sends soldiers to find him and asks a physician how to help him recover."
  c[2]['description']="Goneril is married to Albany, Regan to Cornwall. Each receives part of Lear’s kingdom. They dispute the size of his retinue and eventually compete for Edmund. Listen for the moments when cooperation gives way to suspicion."
  c[3]['description']="Gloucester has two sons, Edgar, his heir, and Edmund, born outside marriage. Edmund tricks him into driving Edgar away. Later Gloucester risks his life to find Lear shelter."
  c[4]['description']="Edmund resents the law that makes his brother the heir. His forged letter turns father against son. Listen for the difference between the voice he uses when alone and the concern he performs for his family."
  c[5]['description']="Driven into hiding, Edgar plays Poor Tom, a nearly naked beggar tormented by spirits. He must keep changing his voice to guide his blinded father without revealing his name. This edition gives him the closing lines, as the Folio does."
  q[0].update(quote="if it can sustain this comparison, may be judged to be the most perfect specimen of the dramatic art existing in the world",context="A Defence of Poetry, written in 1821, published in 1840. Excerpt from a comparison with Greek tragedy.")
  q[1].update(quote="It is then the best of all Shakespear’s plays, for it is the one in which he was the most in earnest.",context="Characters of Shakespear’s Plays (1817), “Lear”")
  w[0].update(title="Two endings to the reunion",body="The older play King Leir restores the father to his throne. Shakespeare lets father and daughter meet again, then asks the audience to watch Lear carry Cordelia’s body onstage. Watch what happens to his hope: first a mirror might catch her breath, then a feather seems to move, then he asks the others to look at her lips.")
  w[1].update(title="Who has a roof?",body="Out on the heath, Lear first fights the wind as though it could take orders. At the hovel he notices that the Fool is cold. He begins to picture people who always live without shelter and to ask what he did for them when he was king. Edgar, disguised as Poor Tom, comes out of the straw before Lear has finished reckoning with that question.")
  w[2].update(title="Two fathers who fail to recognize their children",body="Lear has heard Cordelia speak the truth and punishes her for it. Gloucester sees what looks like Edgar’s handwriting and scarcely needs another reason to condemn him. Much later one father recognizes his daughter’s voice and another takes his own son’s arm without knowing who is guiding him. Follow the different paths by which they come to trust their children.")
 else:
  g['title']='Kong Lear';g['estimatedTime']='Ca. 3½ time'
  g['about']="Lear vil give riget fra sig og beholde hundrede riddere. Mens hele hoffet ser på, spørger han sine tre døtre hvem der elsker ham højest. Goneril og Regan svarer som han ønsker. Cordelia, hans yndlingsbarn, siger at hun elsker ham som en datter bør. Lear giver hendes del til søstrene og landsforviser Kent da han protesterer. Kongen af Frankrig gifter sig med Cordelia uden medgift.\n\nOgså jarlen af Gloucester tager fejl af hvilket barn han kan stole på. Hans søn Edmund bruger et falsk brev til at vende ham mod arvingen Edgar. Edgar flygter og forklæder sig som en omstrejfende tigger. Da Lear mister sit husly og Gloucester sit syn, må de to fædre sætte deres lid til mennesker de før knap nok lagde mærke til.\n\nStykket findes i to tidlige trykte udgaver, kvartudgaven fra 1608 og folioudgaven fra 1623. Denne udgave henter tekst fra begge. Den har scenen hvor Lear fører en retssag mod døtrene i deres fravær, og lader som folioudgaven Edgar få de sidste ord."
  for v,(t,tx,ob) in zip(a,[('En prøve på kærlighed','Lear beder sine døtre konkurrere om hvem der elsker ham højest. Hvad hører han i deres svar, og hvad lægger han ikke mærke til?','Jeg vil følge hvordan de tre døtre håndterer kærlighedsprøven, og hvad Lears reaktion røber om ham.'),('Ude i stormen','Midt i stormen lægger Lear mærke til at narren fryser. Lidt senere spørger han hvordan folk uden tag over hovedet overlever sådan en nat. Lyt efter hvem hans tanker kredser om.','Jeg vil læse scenerne på heden med blik for hvad der sker mellem Lear, narren, Kent og den forklædte Edgar.'),('Fædre og børn','Lear har tre døtre, Gloucester to sønner. De stoler hver især på det barn der bedrager dem. Hvem hjælper dem når de mister magten?','Jeg vil sammenholde de to fædres fejltagelser og lægge mærke til hvor deres historier udvikler sig forskelligt.'),('Slutningen','Cordelia og Lear finder hinanden igen. På vej i fængsel forestiller han sig at de skal synge sammen og fortælle historier. Lyt efter hvad der bliver af den fremtid i sidste scene.','Jeg vil undersøge hvad genforeningen mellem far og datter betyder for oplevelsen af slutningen.')]):v.update(title=t,text=tx,angleObjective=ob)
  for v,(n,r,d) in zip(c,[('Kong Lear','Konge af Britannien','Lear siger selv at han er over firs. Han giver både jord og regeringsmagt fra sig, men regner med at beholde titlen, ridderne og døtrenes lydighed. Ude i stormen må han pludselig selv tage stilling til hvor narren skal finde ly.'),('Cordelia','Lears yngste datter','Cordelia svarer sin far ligeud og drager uden medgift bort som dronning af Frankrig. I Dover sender hun soldater ud for at finde ham og spørger en læge hvordan hun bedst kan hjælpe ham.'),('Goneril og Regan','Lears ældste døtre','Goneril er gift med Albany, Regan med Cornwall. De får hver en del af riget og sætter spørgsmålstegn ved størrelsen af deres fars følge. Senere gør de begge krav på Edmund.'),('Jarlen af Gloucester','Edgars og Edmunds far','Gloucester har to sønner. Edgar er hans arving, Edmund er født uden for ægteskab. Edmund lokker ham til at drive Edgar på flugt. Senere sætter Gloucester livet på spil for at finde husly til Lear.'),('Edmund','Gloucesters søn uden for ægteskab','Edmund hader den lov der gør hans bror til arving. Et falsk brev er nok til at vende deres far mod Edgar. Lyt til forskellen på den stemme han bruger når han er alene, og den bekymring han viser sin familie.'),('Edgar','Gloucesters arving','På flugt spiller Edgar stakkels Tom, en næsten nøgen tigger plaget af onde ånder. Da han skal føre sin blinde far, må han igen skifte stemme så faren ikke genkender ham. I denne udgave får Edgar slutreplikken ligesom i folioudgaven.')]):v.update(name=n,role=r,description=d)
  q[0].update(quote='hvis det kan bære denne sammenligning, kan det regnes for det mest fuldkomne eksempel på dramatisk kunst der findes i verden',context='A Defence of Poetry, skrevet i 1821, udgivet i 1840. Uddrag af en sammenligning med græsk tragedie, oversat til dansk.')
  q[1].update(quote='Det er altså det bedste af alle Shakespeares skuespil, fordi det er det hvor han mente det mest alvorligt.',context='Characters of Shakespear’s Plays (1817), kapitlet om Lear. Oversat til dansk.')
  w[0].update(title='Gensynet og dets slutning',body='I det ældre skuespil King Leir får faren sin trone tilbage. Shakespeare lader først far og datter mødes igen. Senere kommer Lear ind på scenen med Cordelias krop i armene. Følg hans håb fra ting til ting. Først kan et spejl måske fange hendes ånde. Så synes en fjer at bevæge sig. Til sidst beder han de andre om at se på hendes læber.')
  w[1].update(title='Hvem har et tag over hovedet?',body='Ude på heden kæmper Lear først mod vinden som om han kunne give den ordrer. Ved skuret ser han at narren fryser. Han begynder at forestille sig de mennesker der altid mangler husly, og spørger hvad han selv gjorde for dem som konge. Før han er færdig med det spørgsmål, kommer Edgar ud af halmen forklædt som stakkels Tom.')
  w[2].update(title='To fædre der ikke kender deres børn',body='Lear hører Cordelia tale sandt og straffer hende for det. Gloucester ser hvad der ligner Edgars håndskrift og behøver knap nok flere beviser før han dømmer sin søn. Langt senere genkender den ene sin datters stemme, mens den anden tager sin egen søns arm uden at vide hvem der fører ham. De går hver sin vej før de lærer at stole på deres børn.')
 wr('onboarding-'+k+'.json',g)
